const t = key => I18N[APP.lang][key] || I18N.en[key] || key;
const esc = s => String(s || '').replace(/[&<>'"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const icon = (name) => ({clock:'◷', chart:'↗', shield:'✓', bolt:'✦', book:'文', target:'◎'}[name] || '•');

function getUser(){ try{return JSON.parse(localStorage.getItem('jnep_user'))}catch{return null} }
function setUser(user){localStorage.setItem('jnep_user',JSON.stringify(user))}
function userKey(){const u=getUser();return u ? u.email.toLowerCase() : 'guest'}
function getResults(key=userKey()){try{return JSON.parse(localStorage.getItem('jnep_results_'+key))||[]}catch{return []}}
function saveResults(list,key=userKey()){localStorage.setItem('jnep_results_'+key,JSON.stringify(list))}
function addCalendarMonths(date,months){const d=new Date(date),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+months);const lastDay=new Date(d.getFullYear(),d.getMonth()+1,0).getDate();d.setDate(Math.min(day,lastDay));return d}
function getSubscription(){const u=getUser();return u?.subscription||null}
function isPremium(){const u=getUser(),subscription=u?.subscription;if(!subscription||subscription.status!=='active'||!['premium','premium-3months'].includes(subscription.plan))return false;if(APP.runtimeLoaded&&!APP.subscriptionVerified)return false;const months=subscription.plan==='premium-3months'?3:1;if(!subscription.expiresAt){const purchased=new Date(subscription.purchasedAt||Date.now());subscription.purchasedAt=Number.isNaN(purchased.getTime())?new Date().toISOString():purchased.toISOString();subscription.durationMonths=months;subscription.expiresAt=addCalendarMonths(new Date(subscription.purchasedAt),months).toISOString();setUser({...u,subscription})}if(new Date(subscription.expiresAt).getTime()<=Date.now()){subscription.status='expired';setUser({...u,subscription});return false}return true}
function subscriptionName(subscription){return subscription?.plan==='premium-3months'?t('premiumThreePlan'):t('premiumPlanName')}
function subscriptionPrice(subscription){return subscription?.plan==='premium-3months'?t('premiumThreePrice'):t('premiumPrice')}
function subscriptionDuration(subscription){return subscription?.plan==='premium-3months'?t('threeMonthsAccess'):t('oneMonthAccess')}
function formatSubscriptionDate(iso){return iso?new Date(iso).toLocaleDateString(APP.lang==='ne'?'ne-NP':'en-GB',{year:'numeric',month:'long',day:'numeric'}):''}
const DEV_PREMIUM_TOKEN='jnep-owner-2026';
function initializeDevPremiumMode(){try{const search=(typeof window!=='undefined'&&window.location?window.location.search:'')||'';const mode=new URLSearchParams(search).get('dev-premium');if(mode===DEV_PREMIUM_TOKEN)localStorage.setItem('jnep_owner_test_mode','enabled');if(mode==='off')localStorage.removeItem('jnep_owner_test_mode')}catch{}}
function isDevPremiumMode(){return localStorage.getItem('jnep_owner_test_mode')==='enabled'}
function hasPremiumAccess(){return isPremium()}
function formatDuration(seconds){seconds=Math.max(0,seconds);return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
function niceDate(iso){return new Date(iso).toLocaleDateString(APP.lang==='ne'?'ne-NP':'en-GB',{year:'numeric',month:'short',day:'numeric'})}
function cap(s){return s.charAt(0).toUpperCase()+s.slice(1)}
function levelLabel(level){return t(level==='beginner'?'beginner':level==='advanced'?'advanced':'premium')}
function testLabel(level,demo=false){return demo?t('premiumDemo'):levelLabel(level)}
function toast(message){const n=document.getElementById('toast');n.textContent=message;n.classList.add('show');clearTimeout(APP.toast);APP.toast=setTimeout(()=>n.classList.remove('show'),2800)}

