<section class="section"><div class="shell"><div class="section-head"><div><div class="eyebrow">${t('mock')}</div><h2 class="section-title">${t('mockTitle')}</h2><p class="section-lead">${t('mockLead')}</p></div><a href="#mock" data-route="mock" class="btn btn-soft btn-sm">${t('viewTests')}</a></div>${mockCards()}</div></section>
